package net.flovex.core.social;
import net.flovex.core.data.Storage;import org.bukkit.*;import org.bukkit.entity.Player;import java.util.*;
public final class TeamService{
 private final Storage db;public TeamService(Storage d){db=d;}
 private String id(Player p){return p.getUniqueId().toString();}
 private List<Map<String,Object>> membership(Player p){return db.rows("SELECT t.*,m.role FROM team_members m JOIN teams t ON t.id=m.team_id WHERE m.uuid=?",id(p));}
 public String create(Player p,String name){if(!membership(p).isEmpty())return "You are already in a team.";if(name.length()<3||name.length()>16)return "Team names must be 3-16 characters.";try{db.transaction(c->{try(var q=c.prepareStatement("INSERT INTO teams(name,owner,created) VALUES(?,?,?)",java.sql.Statement.RETURN_GENERATED_KEYS)){q.setString(1,name);q.setString(2,id(p));q.setLong(3,System.currentTimeMillis());q.executeUpdate();try(var keys=q.getGeneratedKeys()){keys.next();long team=keys.getLong(1);try(var m=c.prepareStatement("INSERT INTO team_members(team_id,uuid,role,joined) VALUES(?,?,?,?)")){m.setLong(1,team);m.setString(2,id(p));m.setString(3,"OWNER");m.setLong(4,System.currentTimeMillis());m.executeUpdate();}}}return null;});return "Team "+name+" created.";}catch(Exception e){return "That team name is already taken.";}}
 public String invite(Player p,Player target){var m=membership(p);if(m.isEmpty())return "You are not in a team.";long team=((Number)m.getFirst().get("id")).longValue();if(!Set.of("OWNER","LEADER").contains(m.getFirst().get("role")))return "Only team leaders can invite.";if(!membership(target).isEmpty())return "That player is already in a team.";db.update("INSERT OR REPLACE INTO team_invites(team_id,inviter,target,expires) VALUES(?,?,?,?)",team,id(p),target.getUniqueId().toString(),System.currentTimeMillis()+120000);target.sendMessage("§b"+p.getName()+" invited you to team "+m.getFirst().get("name")+". Use /team join "+m.getFirst().get("name"));return "Invite sent.";}
 public String join(Player p,String name){if(!membership(p).isEmpty())return "Leave your current team first.";var t=db.rows("SELECT id FROM teams WHERE lower(name)=lower(?)",name);if(t.isEmpty())return "Team not found.";long team=((Number)t.getFirst().get("id")).longValue();var inv=db.rows("SELECT expires FROM team_invites WHERE team_id=? AND target=?",team,id(p));if(inv.isEmpty()||((Number)inv.getFirst().get("expires")).longValue()<System.currentTimeMillis())return "You do not have a valid invite.";db.update("INSERT INTO team_members(team_id,uuid,role,joined) VALUES(?,?,?,?)",team,id(p),"MEMBER",System.currentTimeMillis());db.update("DELETE FROM team_invites WHERE team_id=? AND target=?",team,id(p));return "Joined team "+name+".";}
 public String leave(Player p){var m=membership(p);if(m.isEmpty())return "You are not in a team.";long team=((Number)m.getFirst().get("id")).longValue();if("OWNER".equals(m.getFirst().get("role"))){long n=db.rows("SELECT uuid FROM team_members WHERE team_id=?",team).size();if(n>1)return "Transfer ownership or disband the team first.";db.update("DELETE FROM teams WHERE id=?",team);}else db.update("DELETE FROM team_members WHERE team_id=? AND uuid=?",team,id(p));return "You left the team.";}
 public String kick(Player p,String name){var m=membership(p);if(m.isEmpty()||!"OWNER".equals(m.getFirst().get("role")))return "Only the owner can kick members.";OfflinePlayer target=Bukkit.getOfflinePlayer(name);int n=db.update("DELETE FROM team_members WHERE team_id=? AND uuid=? AND role<>'OWNER'",((Number)m.getFirst().get("id")).longValue(),target.getUniqueId().toString());return n>0?"Member removed.":"Member not found or cannot be removed.";}
 public String disband(Player p){var m=membership(p);if(m.isEmpty()||!"OWNER".equals(m.getFirst().get("role")))return "Only the owner can disband.";db.update("DELETE FROM teams WHERE id=?",((Number)m.getFirst().get("id")).longValue());return "Team disbanded.";}
 public String info(Player p){var m=membership(p);if(m.isEmpty())return "You are not in a team.";var t=m.getFirst();StringBuilder b=new StringBuilder("Team "+t.get("name")+": ");for(var r:db.rows("SELECT uuid,role FROM team_members WHERE team_id=?",t.get("id"))){String n=Bukkit.getOfflinePlayer(UUID.fromString((String)r.get("uuid"))).getName();b.append(n==null?"Unknown":n).append(" [").append(r.get("role")).append("] ");}return b.toString();}
 public String setHome(Player p){var m=membership(p);if(m.isEmpty()||!"OWNER".equals(m.getFirst().get("role")))return "Only the owner can set the team home.";Location l=p.getLocation();db.update("UPDATE teams SET home_world=?,home_x=?,home_y=?,home_z=?,home_yaw=?,home_pitch=? WHERE id=?",l.getWorld().getName(),l.getX(),l.getY(),l.getZ(),l.getYaw(),l.getPitch(),m.getFirst().get("id"));return "Team home set.";}
 public boolean home(Player p){var m=membership(p);if(m.isEmpty())return false;var t=m.getFirst();if(t.get("home_world")==null)return false;World w=Bukkit.getWorld((String)t.get("home_world"));if(w==null)return false;p.teleportAsync(new Location(w,((Number)t.get("home_x")).doubleValue(),((Number)t.get("home_y")).doubleValue(),((Number)t.get("home_z")).doubleValue(),((Number)t.get("home_yaw")).floatValue(),((Number)t.get("home_pitch")).floatValue()));return true;}
 public void chat(Player p,String message){var m=membership(p);if(m.isEmpty())return;long team=((Number)m.getFirst().get("id")).longValue();for(var r:db.rows("SELECT uuid FROM team_members WHERE team_id=?",team)){Player t=Bukkit.getPlayer(UUID.fromString((String)r.get("uuid")));if(t!=null)t.sendMessage("§b[Team] §f"+p.getName()+": "+message);}}
 public String togglePvp(Player p){var m=membership(p);if(m.isEmpty()||!"OWNER".equals(m.getFirst().get("role")))return "Only the owner can change team PvP.";long team=((Number)m.getFirst().get("id")).longValue();boolean on=((Number)m.getFirst().get("pvp")).intValue()==1;db.update("UPDATE teams SET pvp=? WHERE id=?",on?0:1,team);return "Team PvP "+(on?"disabled":"enabled")+".";
 }
}